#!/usr/bin/env python3
"""
trainer_build.py — EIN eigenstaendiges Skript: baut die App + (mit --apk) die APK.
Alle Quelldateien + native Glue sind eingebettet.

  python trainer_build.py --apk
"""

import argparse
import os
import platform
import re
import shutil
import subprocess
import sys
from pathlib import Path

# --------------------------------------------------------------------------
# Konfiguration (per CLI ueberschreibbar)
# --------------------------------------------------------------------------
DEFAULT_APP_ID = "com.deinname.trainer"
DEFAULT_APP_NAME = "Trainer"
DEFAULT_PROJECT = "trainer-app"
DEFAULT_SOURCES = "sources"

WEB_TS_FILES = [
    "main.ts", "ble.ts", "training.ts", "recorder.ts",
    "bleAdapter.ts", "foregroundService.ts", "exportCsv.ts", "ftms.ts",
    "interval.ts",
]

# Eingebettete Web-/TS-Quelldateien (base64).
WEB_FILES = {
    'index.html': "",
    'main.ts': "",
    'ble.ts': "",
    'training.ts': "",
    'recorder.ts': "",
    'bleAdapter.ts': "",
    'foregroundService.ts': "",
    'exportCsv.ts': "",
    'ftms.ts': "",
    'interval.ts': "",
}

IS_WINDOWS = platform.system() == "Windows"


# --------------------------------------------------------------------------
# Hilfsfunktionen
# --------------------------------------------------------------------------
def log(msg):     print(f"\033[36m▶ {msg}\033[0m")
def ok(msg):      print(f"\033[32m✓ {msg}\033[0m")
def warn(msg):    print(f"\033[33m! {msg}\033[0m")
def fail(msg):
    print(f"\033[31m✗ {msg}\033[0m")
    sys.exit(1)


def tool(name):
    """Findet ein Kommandozeilen-Tool (unter Windows z.B. npm.cmd)."""
    path = shutil.which(name) or (shutil.which(name + ".cmd") if IS_WINDOWS else None)
    return path


def run(cmd, cwd=None):
    """Fuehrt ein Kommando aus, streamt die Ausgabe, bricht bei Fehler ab."""
    printable = " ".join(str(c) for c in cmd)
    log(printable + (f"   (in {cwd})" if cwd else ""))
    result = subprocess.run(cmd, cwd=cwd)
    if result.returncode != 0:
        fail(f"Kommando fehlgeschlagen (Code {result.returncode}): {printable}")


def check_prereqs():
    log("Pruefe Voraussetzungen …")
    for t in ("node", "npm", "npx"):
        if not tool(t):
            fail(f"'{t}' nicht gefunden. Bitte Node.js 22+ installieren.")
    node_v = subprocess.run([tool("node"), "-v"], capture_output=True, text=True).stdout.strip()
    ok(f"Node {node_v}")


# --------------------------------------------------------------------------
# JDK / JAVA_HOME automatisch ermitteln (Android-Studio-JBR)
# --------------------------------------------------------------------------
def _java_home_valid(home: Path) -> bool:
    exe = "java.exe" if IS_WINDOWS else "java"
    try:
        return (home / "bin" / exe).exists()
    except OSError:
        return False


def find_studio_jdk():
    """Sucht das von Android Studio gebundelte JBR/JRE-JDK. Gibt Path oder None."""
    home = Path.home()
    candidates = []

    if IS_WINDOWS:
        pf = os.environ.get("ProgramFiles", r"C:\Program Files")
        la = os.environ.get("LOCALAPPDATA", str(home / "AppData" / "Local"))
        bases = [
            Path(pf) / "Android" / "Android Studio",
            Path(la) / "Programs" / "Android Studio",
        ]
        for b in bases:
            candidates += [b / "jbr", b / "jre"]
        tb = Path(la) / "JetBrains" / "Toolbox" / "apps"
        if tb.exists():
            candidates += list(tb.glob("AndroidStudio*/**/jbr"))

    elif platform.system() == "Darwin":
        apps = [
            Path("/Applications/Android Studio.app"),
            Path("/Applications/Android Studio Preview.app"),
            home / "Applications" / "Android Studio.app",
        ]
        for a in apps:
            candidates += [
                a / "Contents" / "jbr" / "Contents" / "Home",
                a / "Contents" / "jre" / "Contents" / "Home",
            ]
        tb = home / "Library" / "Application Support" / "JetBrains" / "Toolbox" / "apps"
        if tb.exists():
            candidates += list(tb.glob("AndroidStudio*/**/Contents/jbr/Contents/Home"))

    else:  # Linux
        bases = [
            Path("/opt/android-studio"),
            home / "android-studio",
            Path("/usr/local/android-studio"),
            Path("/snap/android-studio/current/android-studio"),
        ]
        for b in bases:
            candidates += [b / "jbr", b / "jre"]
        tb = home / ".local" / "share" / "JetBrains" / "Toolbox" / "apps"
        if tb.exists():
            candidates += list(tb.glob("AndroidStudio*/**/jbr"))

    for c in candidates:
        if _java_home_valid(c):
            return c
    return None


def _apply_java_home(home: Path, why: str):
    os.environ["JAVA_HOME"] = str(home)
    os.environ["PATH"] = str(home / "bin") + os.pathsep + os.environ.get("PATH", "")
    ok(f"JAVA_HOME gesetzt ({why}): {home}")


def configure_java(explicit=None):
    """Setzt JAVA_HOME fuer den Gradle-Build. Prioritaet:
       1) --java-home  2) vorhandenes gueltiges JAVA_HOME  3) Auto-Suche Studio-JBR."""
    if explicit:
        home = Path(explicit).expanduser().resolve()
        if not _java_home_valid(home):
            fail(f"--java-home ungueltig: {home} (kein bin/java gefunden)")
        _apply_java_home(home, "explizit angegeben")
        return True

    cur = os.environ.get("JAVA_HOME")
    if cur and _java_home_valid(Path(cur)):
        ok(f"JAVA_HOME bereits gesetzt: {cur}")
        os.environ["PATH"] = str(Path(cur) / "bin") + os.pathsep + os.environ.get("PATH", "")
        return True

    found = find_studio_jdk()
    if found:
        _apply_java_home(found, "Android-Studio-JDK automatisch gefunden")
        return True

    warn("Kein JDK gefunden. Bitte Android Studio installieren oder "
         "--java-home <pfad-zum-jbr> angeben. Beispiele fuer den JBR-Pfad:")
    if IS_WINDOWS:
        warn(r'  C:\Program Files\Android\Android Studio\jbr')
    elif platform.system() == "Darwin":
        warn("  /Applications/Android Studio.app/Contents/jbr/Contents/Home")
    else:
        warn("  /opt/android-studio/jbr")
    return False


# --------------------------------------------------------------------------
# Native Java-Glue (eingebettet, damit der Package-Name garantiert stimmt)
# Platzhalter: __APP_ID__
# --------------------------------------------------------------------------
MAIN_ACTIVITY_JAVA = """package __APP_ID__;

import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        registerPlugin(TrainingServicePlugin.class);
        super.onCreate(savedInstanceState);
    }
}
"""

PLUGIN_JAVA = """package __APP_ID__;

import android.content.Context;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.Build;
import android.os.PowerManager;
import android.provider.Settings;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;

@CapacitorPlugin(name = "TrainingService")
public class TrainingServicePlugin extends Plugin {

    @PluginMethod
    public void start(PluginCall call) {
        Intent i = new Intent(getContext(), TrainingForegroundService.class);
        i.setAction(TrainingForegroundService.ACTION_START);
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            getContext().startForegroundService(i);
        } else {
            getContext().startService(i);
        }
        call.resolve();
    }

    @PluginMethod
    public void stop(PluginCall call) {
        getContext().stopService(new Intent(getContext(), TrainingForegroundService.class));
        call.resolve();
    }

    @PluginMethod
    public void playCue(PluginCall call) {
        String type = call.getString("type");
        if (type == null) { call.reject("type fehlt"); return; }
        Intent i = new Intent(getContext(), TrainingForegroundService.class);
        i.setAction(TrainingForegroundService.ACTION_CUE);
        i.putExtra(TrainingForegroundService.EXTRA_CUE_TYPE, type);
        getContext().startService(i);
        call.resolve();
    }

    /** POST_NOTIFICATIONS zur Laufzeit anfragen (Android 13+). Ohne die Erlaubnis
        startet der Foreground-Service nicht zuverlaessig -> keine Toene bei Display-aus. */
    @PluginMethod
    public void requestNotifications(PluginCall call) {
        if (Build.VERSION.SDK_INT >= 33 && getActivity() != null) {
            String perm = "android.permission.POST_NOTIFICATIONS";
            if (ContextCompat.checkSelfPermission(getContext(), perm) != PackageManager.PERMISSION_GRANTED) {
                ActivityCompat.requestPermissions(getActivity(), new String[]{ perm }, 9910);
            }
        }
        call.resolve();
    }

    /** Prueft, ob die App von der Akku-Optimierung ausgenommen ist. */
    @PluginMethod
    public void isIgnoringBatteryOptimizations(PluginCall call) {
        boolean ok = true;
        if (Build.VERSION.SDK_INT >= 23) {
            PowerManager pm = (PowerManager) getContext().getSystemService(Context.POWER_SERVICE);
            ok = pm != null && pm.isIgnoringBatteryOptimizations(getContext().getPackageName());
        }
        JSObject ret = new JSObject();
        ret.put("value", ok);
        call.resolve(ret);
    }

    /** Oeffnet den System-Dialog, um die App von der Akku-Optimierung auszunehmen. */
    @PluginMethod
    public void requestDisableBatteryOptimization(PluginCall call) {
        try {
            Intent i = new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS);
            i.setData(Uri.parse("package:" + getContext().getPackageName()));
            i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
            getContext().startActivity(i);
        } catch (Exception e) { /* ignorieren */ }
        call.resolve();
    }
}
"""

SERVICE_JAVA = """package __APP_ID__;

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.Service;
import android.content.Context;
import android.content.Intent;
import android.content.pm.ServiceInfo;
import android.media.AudioManager;
import android.media.ToneGenerator;
import android.os.Build;
import android.os.Handler;
import android.os.IBinder;
import android.os.Looper;
import android.os.PowerManager;
import androidx.annotation.Nullable;
import androidx.core.app.NotificationCompat;

public class TrainingForegroundService extends Service {

    public static final String ACTION_START = "START";
    public static final String ACTION_STOP = "STOP";
    public static final String ACTION_CUE = "CUE";
    public static final String EXTRA_CUE_TYPE = "cueType";

    private static final String CHANNEL_ID = "training_session";
    private static final int NOTIF_ID = 4711;
    private static final String WAKE_TAG = "trainer::sessionWakeLock";

    private PowerManager.WakeLock wakeLock;
    private ToneGenerator toneGen;
    private final Handler handler = new Handler(Looper.getMainLooper());

    @Nullable
    @Override
    public IBinder onBind(Intent intent) { return null; }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        String action = intent != null ? intent.getAction() : null;
        if (ACTION_STOP.equals(action)) {
            stopSelf();
            return START_NOT_STICKY;
        } else if (ACTION_CUE.equals(action)) {
            playCue(intent.getStringExtra(EXTRA_CUE_TYPE));
            return START_STICKY;
        } else {
            startAsForeground();
        }
        return START_STICKY;
    }

    private void startAsForeground() {
        // Zuerst CPU wach halten und Tongenerator bereitstellen - unabhaengig davon,
        // ob das Posten der Notification auf diesem Geraet Probleme macht.
        acquireWakeLock();
        ensureToneGen();
        createChannel();

        Notification n = new NotificationCompat.Builder(this, CHANNEL_ID)
                .setContentTitle("Training laeuft")
                .setContentText("Leistung wird aufgezeichnet - Zonen-Toene aktiv")
                .setSmallIcon(getApplicationInfo().icon)
                .setOngoing(true)
                .setPriority(NotificationCompat.PRIORITY_LOW)
                .build();

        try {
            if (Build.VERSION.SDK_INT >= 34) {
                startForeground(NOTIF_ID, n, ServiceInfo.FOREGROUND_SERVICE_TYPE_CONNECTED_DEVICE);
            } else {
                startForeground(NOTIF_ID, n);
            }
        } catch (Exception e) {
            // Notification/FGS-Problem (z.B. fehlende Berechtigung) -> Wake-Lock bleibt aktiv.
        }
    }

    private void ensureToneGen() {
        if (toneGen == null) {
            try { toneGen = new ToneGenerator(AudioManager.STREAM_ALARM, 100); }
            catch (Exception e) { /* z.B. Audio-Ressource belegt */ }
        }
    }

    private void acquireWakeLock() {
        if (wakeLock != null && wakeLock.isHeld()) return;
        PowerManager pm = (PowerManager) getSystemService(Context.POWER_SERVICE);
        wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, WAKE_TAG);
        wakeLock.setReferenceCounted(false);
        wakeLock.acquire(4L * 60 * 60 * 1000);
    }

    private void playCue(final String type) {
        if (type == null) return;
        ensureToneGen();              // falls der Service zwischenzeitlich neu gestartet wurde
        acquireWakeLock();
        if (toneGen == null) return;
        if (type.equals("too_high")) {
            toneGen.startTone(ToneGenerator.TONE_CDMA_HIGH_L, 150);
            handler.postDelayed(new Runnable() {
                @Override public void run() {
                    if (toneGen != null) toneGen.startTone(ToneGenerator.TONE_CDMA_HIGH_L, 150);
                }
            }, 220);
        } else if (type.equals("too_low")) {
            toneGen.startTone(ToneGenerator.TONE_CDMA_LOW_L, 400);
        } else if (type.equals("back_in_zone")) {
            toneGen.startTone(ToneGenerator.TONE_PROP_ACK, 180);
        }
    }

    private void createChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            NotificationManager mgr = getSystemService(NotificationManager.class);
            if (mgr.getNotificationChannel(CHANNEL_ID) == null) {
                NotificationChannel ch = new NotificationChannel(
                        CHANNEL_ID, "Trainingssitzung", NotificationManager.IMPORTANCE_LOW);
                ch.setShowBadge(false);
                mgr.createNotificationChannel(ch);
            }
        }
    }

    @Override
    public void onDestroy() {
        handler.removeCallbacksAndMessages(null);
        if (toneGen != null) { toneGen.release(); toneGen = null; }
        if (wakeLock != null && wakeLock.isHeld()) wakeLock.release();
        wakeLock = null;
        super.onDestroy();
    }
}
"""

CAP_CONFIG_TS = """import type { CapacitorConfig } from '@capacitor/cli';

const config: CapacitorConfig = {
  appId: '__APP_ID__',
  appName: '__APP_NAME__',
  webDir: 'dist'
};

export default config;
"""

PERMS_SNIPPET = """    <uses-permission android:name="android.permission.BLUETOOTH_SCAN" android:usesPermissionFlags="neverForLocation" />
    <uses-permission android:name="android.permission.BLUETOOTH_CONNECT" />
    <uses-permission android:name="android.permission.BLUETOOTH" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.BLUETOOTH_ADMIN" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_CONNECTED_DEVICE" />
    <uses-permission android:name="android.permission.WAKE_LOCK" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
"""


# --------------------------------------------------------------------------
# Build-Schritte
# --------------------------------------------------------------------------
def scaffold_vite(project: Path):
    if project.exists() and any(project.iterdir()):
        ok(f"Projekt '{project.name}' existiert bereits — Scaffold uebersprungen")
        return
    log("Erzeuge Vite-Vanilla-TS-Projekt …")
    run([tool("npm"), "create", "vite@latest", project.name, "--",
         "--template", "vanilla-ts"], cwd=project.parent)
    ok("Vite-Projekt erzeugt")


def install_deps(project: Path):
    run([tool("npm"), "install"], cwd=project)
    run([tool("npm"), "install",
         "@capacitor/core", "@capacitor/android",
         "@capacitor-community/bluetooth-le",
         "@capacitor/filesystem", "@capacitor/share",
         "xlsx@0.18.5"], cwd=project)
    run([tool("npm"), "install", "-D", "@capacitor/cli"], cwd=project)
    ok("Abhaengigkeiten installiert")


def write_config(project: Path, app_id: str, app_name: str):
    content = CAP_CONFIG_TS.replace("__APP_ID__", app_id).replace("__APP_NAME__", app_name)
    (project / "capacitor.config.ts").write_text(content, encoding="utf-8")
    ok("capacitor.config.ts geschrieben")


def write_web_sources(project: Path):
    import base64 as _b64
    (project / "index.html").write_bytes(_b64.b64decode(WEB_FILES["index.html"]))
    src = project / "src"
    src.mkdir(exist_ok=True)
    for f in WEB_TS_FILES:
        (src / f).write_bytes(_b64.b64decode(WEB_FILES[f]))
    for junk in ("counter.ts", "style.css", "typescript.svg"):
        jp = src / junk
        if jp.exists():
            jp.unlink()
    ok("Web-/TS-Dateien geschrieben (eingebettet)")


def web_build(project: Path):
    run([tool("npm"), "run", "build"], cwd=project)
    ok("Web-Frontend gebaut (dist/)")


def add_android(project: Path):
    if (project / "android").exists():
        ok("Android-Plattform existiert bereits — uebersprungen")
        return
    run([tool("npx"), "cap", "add", "android"], cwd=project)
    ok("Android-Plattform hinzugefuegt")


def find_main_activity_dir(project: Path) -> Path:
    base = project / "android" / "app" / "src" / "main"
    for root, _dirs, files in os.walk(base):
        for f in files:
            if f.startswith("MainActivity."):
                return Path(root)
    fail("MainActivity nicht gefunden — ist 'cap add android' durchgelaufen?")


def place_native(project: Path, app_id: str):
    pkg_dir = find_main_activity_dir(project)
    log(f"Native Dateien nach {pkg_dir} …")

    # bestehende MainActivity (Java ODER Kotlin) entfernen
    for old in ("MainActivity.java", "MainActivity.kt"):
        op = pkg_dir / old
        if op.exists():
            op.unlink()

    (pkg_dir / "MainActivity.java").write_text(
        MAIN_ACTIVITY_JAVA.replace("__APP_ID__", app_id), encoding="utf-8")
    (pkg_dir / "TrainingServicePlugin.java").write_text(
        PLUGIN_JAVA.replace("__APP_ID__", app_id), encoding="utf-8")
    (pkg_dir / "TrainingForegroundService.java").write_text(
        SERVICE_JAVA.replace("__APP_ID__", app_id), encoding="utf-8")
    ok("MainActivity + Plugin + Foreground-Service (Java) geschrieben")

    patch_manifest(project, app_id)


def patch_manifest(project: Path, app_id: str):
    manifest = project / "android" / "app" / "src" / "main" / "AndroidManifest.xml"
    xml = manifest.read_text(encoding="utf-8")

    if "TrainingForegroundService" in xml:
        ok("AndroidManifest bereits gepatcht — uebersprungen")
        return

    # Berechtigungen direkt nach dem oeffnenden <manifest ...> einfuegen
    m = re.search(r"<manifest\b[^>]*>", xml)
    if not m:
        fail("Konnte <manifest>-Tag nicht finden.")
    xml = xml[:m.end()] + "\n" + PERMS_SNIPPET + xml[m.end():]

    # Service-Deklaration vor </application> einfuegen
    service = (f'        <service\n'
               f'            android:name="{app_id}.TrainingForegroundService"\n'
               f'            android:exported="false"\n'
               f'            android:foregroundServiceType="connectedDevice" />\n')
    if "</application>" not in xml:
        fail("Konnte </application> nicht finden.")
    xml = xml.replace("</application>", service + "    </application>", 1)

    manifest.write_text(xml, encoding="utf-8")
    ok("AndroidManifest gepatcht (Berechtigungen + Service)")


def cap_sync(project: Path):
    run([tool("npx"), "cap", "sync"], cwd=project)
    ok("cap sync abgeschlossen")


def build_apk(project: Path, java_home=None):
    if not configure_java(java_home):
        fail("Ohne JDK kann die APK nicht gebaut werden (siehe Hinweis oben).")
    android = project / "android"
    gradlew = android / ("gradlew.bat" if IS_WINDOWS else "gradlew")
    if not gradlew.exists():
        fail("gradlew nicht gefunden.")
    if not IS_WINDOWS:
        os.chmod(gradlew, 0o755)
    log("Baue Debug-APK via Gradle (kann beim ersten Mal dauern) …")
    run([str(gradlew), "assembleDebug"], cwd=android)
    apk = android / "app" / "build" / "outputs" / "apk" / "debug" / "app-debug.apk"
    if apk.exists():
        ok(f"APK gebaut: {apk}")
    else:
        warn("Gradle lief durch, aber die APK wurde nicht am erwarteten Ort gefunden.")


# --------------------------------------------------------------------------
# Main
# --------------------------------------------------------------------------
def main():
    ap = argparse.ArgumentParser(description="Baut die Powerzonen-Trainings-App.")
    ap.add_argument("--dir", default=DEFAULT_PROJECT, help="Projektordner (Default: trainer-app)")
    ap.add_argument("--app-id", default=DEFAULT_APP_ID, help="Android App-ID / Package")
    ap.add_argument("--app-name", default=DEFAULT_APP_NAME, help="App-Name")
    ap.add_argument("--apk", action="store_true", help="Zusaetzlich die Debug-APK bauen")
    ap.add_argument("--java-home", default=None,
                    help="Pfad zum JDK (sonst Auto-Suche nach dem Android-Studio-JBR)")
    ap.add_argument("--skip-build", action="store_true", help="npm run build ueberspringen")
    args = ap.parse_args()

    project = Path(args.dir).resolve()

    print(f"\n=== Powerzonen-Trainings-App Build (One-File) ===")
    print(f"Projekt : {project}")
    print(f"App-ID  : {args.app_id}\n")

    check_prereqs()
    scaffold_vite(project)
    install_deps(project)
    write_config(project, args.app_id, args.app_name)
    write_web_sources(project)
    if not args.skip_build:
        web_build(project)
    add_android(project)
    place_native(project, args.app_id)
    cap_sync(project)
    if args.apk:
        build_apk(project, args.java_home)

    print("\n\033[32m=== Fertig ===\033[0m")
    print("Naechste Schritte:")
    print(f"  • In Android Studio oeffnen:   npx cap open android   (im Ordner {project.name})")
    print("  • Handy per USB anschliessen (USB-Debugging an) und Run ▶ druecken.")
    print("  • BLE braucht ein ECHTES Geraet — der Emulator hat kein Bluetooth.")
    print("  • Tipp: In der App vor dem ersten Start POST_NOTIFICATIONS erlauben und")
    print("    die Akku-Optimierung fuer die App deaktivieren (fuer Screen-off-Toene).")
    if not args.apk:
        print("  • APK direkt bauen:            python build_app.py --apk")


if __name__ == "__main__":
    main()
